// Fails when a tracked text file contains a typographic character forbidden by
// core rule 00 (Keyboard characters only). The project's CI runs it (core
// rule 05, Formatting). Exclusions come from the project's
// .agents/keyboard-characters.json, each with its reason:
//
//   { "exclude": [{ "path": "pnpm-lock.yaml", "reason": "generated by pnpm" },
//                 { "path": ".agents/skills/vendored/", "reason": "verbatim" }] }
//
// A path ending in "/" excludes a directory.
import { execFileSync } from "node:child_process"
import { existsSync, readFileSync } from "node:fs"

import {
  C1_NUMERIC_REFERENCES,
  LEGACY_NAMED_ENTITIES,
  NAMED_ENTITIES,
} from "./forbidden-html-entities.mjs"

// Each range is inclusive and matches the forbidden list in rule 00. Arrows are
// the Unicode arrow blocks (Arrows, Supplemental Arrows-A/B/C) and the arrow
// characters of Dingbats, Miscellaneous Symbols and Arrows and Halfwidth Forms.
const FORBIDDEN = [
  ["dashes", 0x2010, 0x2015],
  ["dashes", 0x2e3a, 0x2e3b],
  ["quotes", 0x2018, 0x201f],
  ["quotes", 0x00ab, 0x00ab],
  ["quotes", 0x00bb, 0x00bb],
  ["quotes", 0x2039, 0x203a],
  ["ellipsis", 0x2026, 0x2026],
  ["arrows", 0x2190, 0x21ff],
  ["arrows", 0x2794, 0x2794],
  ["arrows", 0x2798, 0x27af],
  ["arrows", 0x27b1, 0x27be],
  ["arrows", 0x27f0, 0x27ff],
  ["arrows", 0x2900, 0x297f],
  ["arrows", 0x2b00, 0x2b11],
  ["arrows", 0x2b30, 0x2b4f],
  ["arrows", 0x2b5a, 0x2b73],
  ["arrows", 0x2b76, 0x2b7d],
  ["arrows", 0x2b80, 0x2b8f],
  ["arrows", 0x2b94, 0x2b95],
  ["arrows", 0x2b98, 0x2bb9],
  ["arrows", 0x2bec, 0x2bef],
  ["arrows", 0xffe9, 0xffec],
  ["arrows", 0x1f800, 0x1f8ff],
  ["bullets and middle dots", 0x00b7, 0x00b7],
  ["bullets and middle dots", 0x2022, 0x2023],
  ["bullets and middle dots", 0x2027, 0x2027],
  ["bullets and middle dots", 0x2043, 0x2043],
  ["bullets and middle dots", 0x2219, 0x2219],
  ["bullets and middle dots", 0x22c5, 0x22c5],
  ["special spaces", 0x00a0, 0x00a0],
  ["special spaces", 0x2000, 0x200d],
  ["special spaces", 0x202f, 0x202f],
  ["special spaces", 0x205f, 0x2060],
  ["special spaces", 0x3000, 0x3000],
  ["special spaces", 0xfeff, 0xfeff],
]

const CONFIG = ".agents/keyboard-characters.json"

/** The project's exclusions; an entry without a reason is a configuration error. */
function readExclusions() {
  if (!existsSync(CONFIG)) return []
  const { exclude = [] } = JSON.parse(readFileSync(CONFIG, "utf8"))
  for (const entry of exclude) {
    if (
      typeof entry.path !== "string" ||
      !entry.path ||
      typeof entry.reason !== "string" ||
      !entry.reason.trim()
    ) {
      throw new Error(`${CONFIG}: every exclusion needs a path and a reason`)
    }
  }
  return exclude.map((entry) => entry.path)
}

const EXCLUSIONS = readExclusions()

function isExcluded(path) {
  return EXCLUSIONS.some((excluded) =>
    excluded.endsWith("/") ? path.startsWith(excluded) : path === excluded
  )
}

function forbiddenCategory(codePoint) {
  const match = FORBIDDEN.find(
    ([, first, last]) => codePoint >= first && codePoint <= last
  )
  return match?.[0]
}

// Escaped forms render the same characters. Each decoder yields the escape's
// position, its text and the code point it renders.
function* decodeMatches(line, pattern, decode) {
  for (const match of line.matchAll(pattern)) {
    yield { index: match.index, text: match[0], codePoint: decode(match) }
  }
}

// HTML also decodes numeric references without the semicolon, maps the C1
// range to Windows-1252 and decodes a few legacy names without the semicolon.
function numericReference(value) {
  return C1_NUMERIC_REFERENCES[value] ?? value
}

function legacyEntity(name) {
  const legacy = Object.keys(LEGACY_NAMED_ENTITIES).find((candidate) =>
    name.startsWith(candidate)
  )
  return legacy === undefined ? undefined : LEGACY_NAMED_ENTITIES[legacy]
}

function htmlReferences(line) {
  return [
    ...decodeMatches(line, /&#[xX]([0-9a-fA-F]+);?/g, (match) =>
      numericReference(parseInt(match[1], 16))
    ),
    ...decodeMatches(line, /&#(\d+);?/g, (match) =>
      numericReference(parseInt(match[1], 10))
    ),
    ...decodeMatches(line, /&([A-Za-z][A-Za-z0-9]*)(;?)/g, (match) =>
      match[2] ? NAMED_ENTITIES[match[1]] : legacyEntity(match[1])
    ),
  ]
}

const HIGH_SURROGATE = [0xd800, 0xdbff]
const LOW_SURROGATE = [0xdc00, 0xdfff]
const within = (value, [first, last]) => value >= first && value <= last

// JavaScript and JSON `\u` escapes; two adjacent escapes forming a surrogate
// pair encode one character outside the Basic Multilingual Plane.
function* unicodeEscapes(line) {
  const matches = [
    ...line.matchAll(/\\u(?:\{([0-9a-fA-F]+)\}|([0-9a-fA-F]{4}))/g),
  ]
  for (let i = 0; i < matches.length; i += 1) {
    const match = matches[i]
    const next = matches[i + 1]
    const codePoint = parseInt(match[1] ?? match[2], 16)
    const low = next && parseInt(next[1] ?? next[2], 16)
    if (
      within(codePoint, HIGH_SURROGATE) &&
      next?.index === match.index + match[0].length &&
      within(low, LOW_SURROGATE)
    ) {
      yield {
        index: match.index,
        text: match[0] + next[0],
        codePoint:
          0x10000 +
          (codePoint - HIGH_SURROGATE[0]) * 0x400 +
          low -
          LOW_SURROGATE[0],
      }
      i += 1
    } else {
      yield { index: match.index, text: match[0], codePoint }
    }
  }
}

// CSS escapes are a backslash and one to six hex digits; elsewhere that form is
// not an escape (Windows paths, regular expressions).
function cssEscapes(line) {
  return decodeMatches(line, /\\([0-9a-fA-F]{1,6})/g, (match) =>
    parseInt(match[1], 16)
  )
}

const CSS_FILE = /\.(css|scss|sass|less)$/

function escapedCharacters(path, line) {
  const escapes = [...htmlReferences(line), ...unicodeEscapes(line)]
  return CSS_FILE.test(path) ? [...escapes, ...cssEscapes(line)] : escapes
}

const files = execFileSync("git", ["ls-files", "-z"], { encoding: "utf8" })
  .split("\0")
  .filter((path) => path && !isExcluded(path))

const findings = []

for (const path of files) {
  let buffer
  try {
    buffer = readFileSync(path)
  } catch (error) {
    // A tracked file deleted in the working tree has nothing to check.
    if (error.code === "ENOENT") {
      continue
    }
    throw error
  }

  // Binary files (images, fonts) are not authored text.
  if (buffer.includes(0)) {
    continue
  }

  const report = (line, column, codePoint, category, form) => {
    const hex = codePoint.toString(16).toUpperCase().padStart(4, "0")
    findings.push(`${path}:${line}:${column}: U+${hex} (${category})${form}`)
  }

  const lines = buffer.toString("utf8").split("\n")
  lines.forEach((line, index) => {
    let column = 0
    for (const character of line) {
      column += 1
      const codePoint = character.codePointAt(0)
      const category = forbiddenCategory(codePoint)
      if (category) {
        report(index + 1, column, codePoint, category, "")
      }
    }

    for (const escape of escapedCharacters(path, line)) {
      const category =
        escape.codePoint === undefined
          ? undefined
          : forbiddenCategory(escape.codePoint)
      if (category) {
        const column = [...line.slice(0, escape.index)].length + 1
        report(
          index + 1,
          column,
          escape.codePoint,
          category,
          ` as ${escape.text}`
        )
      }
    }
  })
}

if (findings.length > 0) {
  console.error(findings.join("\n"))
  console.error(
    `\n${findings.length} forbidden typographic character(s). Use keyboard characters only (core rule 00).`
  )
  process.exit(1)
}

console.log(`Keyboard characters only: ${files.length} tracked files checked.`)
